def perimeter_diamond(n):
    cells = []
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if abs(x) + abs(y) <= n:
                cells.append((x, y))

    boundary_edges = set()
    for x, y in cells:
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if abs(nx) + abs(ny) > n:
                # This is a boundary edge
                edge = tuple(sorted([(x, y), (nx, ny)]))
                boundary_edges.add(edge)
    return len(boundary_edges)

for n in range(1, 11):
    print(f"n={n}, perimeter={perimeter_diamond(n)}")
